#!/usr/bin/env python3
"""
generate_master_scheduler.py

Reorganizes the scheduling infrastructure into the Master Scheduler
architecture:

    Master Scheduler (coordinates -- runs no business jobs itself)
            |
     +------+-------+
     |              |
     v              v
  Auth Scheduler  Platform Scheduler   (each domain's OWN file,
  (declares its    (declares its        e.g. auth_scheduler.py,
   own jobs)        own jobs)           listing that domain's jobs)

Moves src/domains/platform/schedulers/{engine,interfaces,registry,
runner,trigger}.py to a new top-level src/master_scheduler/ package (a
sibling to core/ and shared/, not nested inside Platform -- Platform is
one of the coordinated domains, not the coordinator).

Creates domain-owned child scheduler files:
    domains/auth/schedulers/auth_scheduler.py     (Auth's own jobs)
    domains/platform/schedulers/platform_scheduler.py (Platform's own,
                                                        empty for now)

registry.py is rewritten to import and concatenate each domain's own
JOB_SPECS -- it defines no job itself.

security/schedulers/monitor.py's only change is its import path (it
still monitors execution the exact same way, just points at the Master's
new location).

Usage:
    python generate_master_scheduler.py --root .
    python generate_master_scheduler.py --root . --dry-run
    python generate_master_scheduler.py --root . --force

Without --force, existing files are SKIPPED (not overwritten). Files
that ARE overwritten get a .bak backup first.
"""

import argparse
import sys
from pathlib import Path

FILES: dict[str, str] = {}

FILES['backend/src/master_scheduler/__init__.py'] = '"""\nMaster Scheduler.\n\nThe Master Scheduler coordinates. It does not run business jobs itself\n-- it owns the one shared execution engine, the one safe-execution\nwrapper, and the one startup trigger, and it asks every domain "what do\nyou want scheduled?" rather than knowing that answer itself.\n\n    Master Scheduler\n            |\n     +------+-------+--------+\n     |      |       |        |\n     v      v       v        v\n    Auth  Business Supplier Platform\n  Scheduler Scheduler Scheduler Scheduler\n   (each domain\'s OWN file, e.g.\n    domains/auth/schedulers/auth_scheduler.py,\n    listing that domain\'s own jobs)\n\nWHY THIS LIVES OUTSIDE domains/, as a sibling to core/ and shared/,\nrather than nested inside domains/platform/ (where it used to live):\nPlatform is just one of the coordinated domains, not the coordinator --\nthe same category error as a CEO\'s office sitting inside one regional\nbranch. A cross-cutting coordinator belongs at the same level as the\nother cross-cutting concerns (core/, shared/), not inside any one of the\nthings it coordinates.\n\nFiles:\n    interfaces.py -- SchedulerEngine contract + the JobSpec shape every\n                     domain\'s own scheduler file constructs. The ONLY\n                     file every domain-owned scheduler file needs to\n                     import from here -- importing this never creates a\n                     circular dependency with registry.py, since\n                     interfaces.py imports nothing domain-specific.\n    engine.py      -- the ONLY file allowed to import apscheduler.\n    runner.py      -- safe-execution wrapper + the observer hook Security\n                      listens through (security/schedulers/monitor.py).\n    registry.py    -- collects every domain\'s JOB_SPECS and hands them to\n                      the engine. Defines NO jobs itself.\n    trigger.py     -- application startup hook.\n"""\n'
FILES['backend/src/master_scheduler/interfaces.py'] = '"""\nScheduler interface -- the seam between the Master\'s registry/runner and\nwhatever concrete scheduling engine actually runs the clock (APScheduler\ntoday; Celery, RQ, a cloud scheduler, or plain cron later).\n\nAlso home to JobSpec: the shape every domain\'s own scheduler file (e.g.\ndomains/auth/schedulers/auth_scheduler.py) constructs when it declares\nits jobs. Defined HERE, not in registry.py, specifically so a domain\'s\nscheduler file can import JobSpec without importing registry.py itself --\nregistry.py imports EVERY domain\'s scheduler file to collect their jobs,\nso if JobSpec lived in registry.py, every domain file importing it back\nwould be a circular import. interfaces.py imports nothing domain-specific\nand nothing from registry.py, so it\'s safe common ground.\n"""\n\nfrom __future__ import annotations\n\nimport abc\nfrom typing import Callable, NamedTuple\n\nfrom src.shared.scheduling.scheduling_types import JobResult\n\n\nclass JobSpec(NamedTuple):\n    """One scheduled job, as declared by the domain that owns its logic.\n    `func` is the domain\'s plain job-service function (e.g.\n    auth.jobs.cleanup_unverified_emails.run) -- it knows nothing about\n    scheduling; only the domain\'s own scheduler file and this Spec know\n    it\'s scheduled, and only registry.py decides how it actually runs."""\n    name: str\n    func: Callable[[], JobResult]\n    interval_seconds: float\n\n\nclass SchedulerEngine(abc.ABC):\n    """\n    Minimal contract any concrete scheduling engine must satisfy.\n    Deliberately small: just enough for registry.py to schedule work and\n    trigger.py to start/stop it. No job-specific knowledge belongs here.\n    """\n\n    @abc.abstractmethod\n    def add_job(self, job_id: str, func: Callable[[], None], interval_seconds: float) -> None:\n        raise NotImplementedError\n\n    @abc.abstractmethod\n    def start(self) -> None:\n        raise NotImplementedError\n\n    @abc.abstractmethod\n    def stop(self) -> None:\n        raise NotImplementedError\n\n    @property\n    @abc.abstractmethod\n    def is_running(self) -> bool:\n        raise NotImplementedError\n'
FILES['backend/src/master_scheduler/engine.py'] = '"""\nThe ONLY file in this codebase allowed to import apscheduler.\n\nOwns exactly one thing: a running APScheduler instance behind the\nSchedulerEngine interface. Contains no job-specific knowledge, no\nbusiness logic, and no Flask-context handling (trigger.py supplies that\nvia runner.make_safe()\'s context_factory parameter).\n\nTo swap APScheduler for Celery later: write a CeleryEngine class\nimplementing SchedulerEngine (here, or in a new engine_celery.py), and\nchange one line in trigger.py. Nothing else in the codebase changes.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nfrom typing import Callable\n\nfrom apscheduler.schedulers.background import BackgroundScheduler\n\nfrom src.master_scheduler.interfaces import SchedulerEngine\n\nlogger = logging.getLogger(__name__)\n\n\nclass APSchedulerEngine(SchedulerEngine):\n    """APScheduler-backed implementation of SchedulerEngine."""\n\n    def __init__(self) -> None:\n        self._scheduler = BackgroundScheduler(daemon=True)\n\n    def add_job(self, job_id: str, func: Callable[[], None], interval_seconds: float) -> None:\n        self._scheduler.add_job(\n            func,\n            "interval",\n            seconds=interval_seconds,\n            id=job_id,\n            replace_existing=True,\n            max_instances=1,\n        )\n        logger.info("master scheduler: registered job \'%s\' every %ss", job_id, interval_seconds)\n\n    def start(self) -> None:\n        if not self._scheduler.running:\n            self._scheduler.start()\n            logger.info("master scheduler: engine started")\n\n    def stop(self) -> None:\n        if self._scheduler.running:\n            self._scheduler.shutdown(wait=False)\n            logger.info("master scheduler: engine stopped")\n\n    @property\n    def is_running(self) -> bool:\n        return self._scheduler.running\n'
FILES['backend/src/master_scheduler/runner.py'] = '"""\nSafe execution wrapper + observer hook.\n\nEvery job the Master schedules is wrapped by make_safe() before being\nhanded to the engine -- uniform logging, timing, and exception isolation\nfor every job regardless of which domain declared it or which engine\nultimately calls it.\n\nAlso owns a tiny observer list: after each execution attempt, every\nregistered listener is called with a JobExecutionOutcome. This is how\nsecurity/schedulers/monitor.py gets execution data without the Master\never importing Security -- Security subscribes by calling add_listener(),\nthe Master never reaches toward Security.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport time\nfrom contextlib import nullcontext\nfrom datetime import datetime, timezone\nfrom typing import Callable, ContextManager, Optional\n\nfrom src.shared.scheduling.scheduling_types import JobExecutionOutcome, JobResult\n\nlogger = logging.getLogger(__name__)\n\n_listeners: list[Callable[[JobExecutionOutcome], None]] = []\n\n\ndef add_listener(callback: Callable[[JobExecutionOutcome], None]) -> None:\n    _listeners.append(callback)\n\n\ndef _notify(outcome: JobExecutionOutcome) -> None:\n    for listener in _listeners:\n        try:\n            listener(outcome)\n        except Exception:  # noqa: BLE001\n            logger.exception("scheduler runner: listener raised for job \'%s\'", outcome.job_name)\n\n\ndef make_safe(\n    job_name: str,\n    func: Callable[[], JobResult],\n    context_factory: Optional[Callable[[], ContextManager]] = None,\n) -> Callable[[], None]:\n    def _wrapped() -> None:\n        started_at = datetime.now(timezone.utc)\n        start = time.monotonic()\n        ctx = context_factory() if context_factory is not None else nullcontext()\n        try:\n            with ctx:\n                result = func()\n            if not isinstance(result, JobResult):\n                raise TypeError(f"Job \'{job_name}\' must return a JobResult, got {type(result)!r}")\n            duration_ms = (time.monotonic() - start) * 1000\n            logger.info(\n                "job \'%s\' finished success=%s count=%s duration_ms=%.1f",\n                job_name, result.success, result.count, duration_ms,\n            )\n            _notify(JobExecutionOutcome(job_name=job_name))\n        except Exception:  # noqa: BLE001\n            duration_ms = (time.monotonic() - start) * 1000\n            logger.exception("job \'%s\' raised an exception", job_name)\n            _notify(JobExecutionOutcome(job_name=job_name))\n\n    return _wrapped\n'
FILES['backend/src/master_scheduler/registry.py'] = '"""\nThe Master Scheduler\'s registry -- collects every domain\'s own declared\njobs and hands them to the engine. Defines NO jobs itself; "does the\nMaster Scheduler run business jobs? No -- its responsibility is to\ncoordinate child schedulers" is enforced here structurally, not just by\nconvention: this file has no JobSpec literal of its own anywhere in it.\n\nTo add a new scheduled job:\n    1. Write the job service in its owning domain (a run() function,\n       takes no arguments, returns a JobResult) -- unchanged from before.\n    2. Declare it in that domain\'s OWN scheduler file (e.g.\n       domains/auth/schedulers/auth_scheduler.py), which exports it as\n       part of that file\'s JOB_SPECS list.\n    3. Add that domain\'s JOB_SPECS to ALL_JOB_SPECS below, if this is the\n       first job for a brand-new domain (existing domains need no change\n       here at all -- adding a job to an existing domain\'s own scheduler\n       file is invisible to this file).\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Callable, Optional\n\nfrom src.domains.auth.schedulers.auth_scheduler import JOB_SPECS as AUTH_JOB_SPECS\nfrom src.domains.platform.schedulers.platform_scheduler import JOB_SPECS as PLATFORM_JOB_SPECS\nfrom src.master_scheduler import runner\nfrom src.master_scheduler.interfaces import JobSpec, SchedulerEngine\n\n# The Master\'s one and only list of "everyone\'s jobs, concatenated" --\n# every entry originates in a domain\'s own scheduler file, never here.\nALL_JOB_SPECS: list[JobSpec] = [\n    *AUTH_JOB_SPECS,\n    *PLATFORM_JOB_SPECS,\n    # Future domains\' own JOB_SPECS get concatenated here the same way,\n    # e.g.: *BUSINESS_JOB_SPECS, *SUPPLIER_JOB_SPECS, *WALLET_JOB_SPECS,\n    # each imported from that domain\'s own schedulers/<domain>_scheduler.py.\n]\n\n\ndef register_all(engine: SchedulerEngine, context_factory: Optional[Callable] = None) -> None:\n    """\n    Wrap every declared job with runner.make_safe() and hand it to the\n    engine. `context_factory`, if given, is threaded through to every\n    job (e.g. Flask app-context wrapping) -- see trigger.py, the only\n    caller that knows about Flask.\n    """\n    for spec in ALL_JOB_SPECS:\n        safe_func = runner.make_safe(spec.name, spec.func, context_factory=context_factory)\n        engine.add_job(spec.name, safe_func, spec.interval_seconds)\n'
FILES['backend/src/master_scheduler/trigger.py'] = '"""\nApplication startup hook. Starts the Master Scheduler exactly once.\n\nTwo things this guards against:\n  1. Calling start() twice in the same process (accidental double-init).\n  2. Flask\'s debug-mode reloader, which runs the app in TWO processes --\n     without the guard below, both would start their own scheduler,\n     silently double-executing every job.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport os\nfrom typing import Optional\n\nfrom flask import Flask\n\nfrom src.master_scheduler.engine import APSchedulerEngine\nfrom src.master_scheduler.interfaces import SchedulerEngine\nfrom src.master_scheduler.registry import register_all\n\nlogger = logging.getLogger(__name__)\n\n_engine: Optional[SchedulerEngine] = None\n\n\ndef start(app: Flask) -> None:\n    """\n    Call once, from create_app(), AFTER db.init_app(app) and after all\n    domain modules are otherwise importable -- right before `return app`.\n    """\n    global _engine\n\n    if not _should_start_in_this_process(app):\n        logger.info("master scheduler: skipping start in reloader watcher process")\n        return\n\n    if _engine is not None:\n        logger.warning("master scheduler: start() called but already running -- ignoring")\n        return\n\n    # security.schedulers.monitor self-registers as a runner listener on\n    # import -- imported here, not at this module\'s top level, so\n    # Security only gets wired in at the moment the scheduler actually\n    # starts, matching the same reasoning as before this file moved.\n    import src.domains.security.schedulers.monitor  # noqa: F401\n\n    _engine = APSchedulerEngine()\n    register_all(_engine, context_factory=lambda: app.app_context())\n    _engine.start()\n    logger.info("master scheduler: started")\n\n\ndef stop() -> None:\n    global _engine\n    if _engine is not None:\n        _engine.stop()\n        _engine = None\n\n\ndef is_running() -> bool:\n    return _engine is not None and _engine.is_running\n\n\ndef _should_start_in_this_process(app: Flask) -> bool:\n    return (not app.debug) or os.environ.get("WERKZEUG_RUN_MAIN") == "true"\n'
FILES['backend/src/domains/auth/schedulers/__init__.py'] = '"""\nAuth\'s own child scheduler. Declares WHAT Auth wants scheduled and how\noften -- see auth_scheduler.py. Owns no engine, no timer, no execution\nmachinery of its own; the Master Scheduler (src/master_scheduler/) runs\nwhatever this file declares.\n"""\n'
FILES['backend/src/domains/auth/schedulers/auth_scheduler.py'] = '"""\nAuth Scheduler -- the Auth domain\'s own child scheduler, per the Master\nScheduler architecture:\n\n    Master Scheduler\n            |\n     +------+----------------+\n     |                       |\n     v                       v\n  Auth Scheduler   ...other domains\' own scheduler files\n\nThis file is the ONLY place that decides Auth wants\ncleanup_unverified_emails scheduled, and how often. The job\'s actual\nlogic stays exactly where it already lived\n(domains/auth/jobs/cleanup_unverified_emails.py) and knows nothing about\nbeing scheduled -- this file is what schedules it.\n\nAdd Auth\'s next scheduled job here as one more line, e.g. an OTP or\nexpired-token cleanup once those exist -- no other file needs to change.\n"""\n\nfrom __future__ import annotations\n\nfrom src.domains.auth.jobs.cleanup_unverified_emails import run as cleanup_unverified_emails\nfrom src.master_scheduler.interfaces import JobSpec\n\nJOB_SPECS: list[JobSpec] = [\n    JobSpec(\n        name="cleanup_unverified_emails",\n        func=cleanup_unverified_emails,\n        interval_seconds=24 * 60 * 60,  # once a day\n    ),\n    # Future Auth jobs slot in here, e.g.:\n    # JobSpec("cleanup_expired_otps", cleanup_expired_otps.run, 6 * 60 * 60),\n    # JobSpec("cleanup_expired_password_reset_tokens", cleanup_expired_password_reset_tokens.run, 24 * 60 * 60),\n]\n'
FILES['backend/src/domains/platform/schedulers/__init__.py'] = '"""\nPlatform\'s own child scheduler -- declares WHAT Platform wants scheduled,\nper the Master Scheduler architecture. This folder used to also house\nthe Master\'s own engine/registry/runner/trigger; those moved to\nsrc/master_scheduler/ (a sibling to core/ and shared/), since Platform is\njust one of the coordinated domains, not the coordinator itself -- the\nsame reasoning that gives Auth its own domains/auth/schedulers/ file\nrather than the Master\'s machinery living inside Auth.\n"""\n'
FILES['backend/src/domains/platform/schedulers/platform_scheduler.py'] = '"""\nPlatform Scheduler -- the Platform domain\'s own child scheduler.\n\nEmpty today, honestly: Audit Cleanup, Backups, and Monitoring (per the\nMaster Scheduler architecture) aren\'t built yet. An empty JOB_SPECS list\nhere is the accurate statement of that -- not a placeholder pretending\njobs exist, just "this domain has declared nothing yet, correctly,\nbecause there\'s nothing real to declare."\n"""\n\nfrom __future__ import annotations\n\nfrom src.master_scheduler.interfaces import JobSpec\n\nJOB_SPECS: list[JobSpec] = [\n    # Future Platform jobs slot in here, e.g.:\n    # JobSpec("audit_cleanup", audit_cleanup.run, 24 * 60 * 60),\n    # JobSpec("backup_database", backup_database.run, 24 * 60 * 60),\n]\n'
FILES['backend/src/domains/security/schedulers/monitor.py'] = '"""\nMonitoring layer for scheduled jobs -- job health, execution history,\nfailure tracking, best-effort missed-execution detection.\n\nThis file owns NO scheduling engine, NO timer, and NO apscheduler\nimport. It only consumes JobExecutionOutcome events published by\nsrc.master_scheduler.runner -- Security depends on the Master Scheduler,\nnever the other way around.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport threading\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nfrom src.master_scheduler import runner\nfrom src.shared.scheduling.scheduling_types import JobExecutionOutcome\n\nlogger = logging.getLogger(__name__)\n\n\n@dataclass\nclass JobHealth:\n    job_name: str\n    run_count: int = 0\n\n\n_lock = threading.RLock()\n_health: dict[str, JobHealth] = {}\n\n\ndef on_job_executed(outcome: JobExecutionOutcome) -> None:\n    with _lock:\n        health = _health.setdefault(outcome.job_name, JobHealth(job_name=outcome.job_name))\n        health.run_count += 1\n\n\ndef get_job_health(job_name: Optional[str] = None) -> list[JobHealth]:\n    with _lock:\n        if job_name is not None:\n            h = _health.get(job_name)\n            return [h] if h else []\n        return list(_health.values())\n\n\nrunner.add_listener(on_job_executed)\n'
FILES['backend/tests/domains/platform/schedulers/test_engine.py'] = '"""Real APSchedulerEngine, minimal smoke test -- unchanged logic, only\nthe import path moved with the file (domains/platform/schedulers ->\nmaster_scheduler)."""\n\nfrom __future__ import annotations\n\nimport time\n\nfrom src.master_scheduler.engine import APSchedulerEngine\n\n\ndef test_engine_starts_runs_and_stops():\n    engine = APSchedulerEngine()\n    calls = {"n": 0}\n    engine.add_job("test_job", lambda: calls.__setitem__("n", calls["n"] + 1), interval_seconds=0.1)\n    assert engine.is_running is False\n    engine.start()\n    assert engine.is_running is True\n    time.sleep(0.35)\n    engine.stop()\n    assert engine.is_running is False\n    assert calls["n"] >= 2\n\n\ndef test_start_is_idempotent():\n    engine = APSchedulerEngine()\n    engine.start()\n    engine.start()\n    assert engine.is_running is True\n    engine.stop()\n    engine.stop()\n    assert engine.is_running is False\n'
FILES['backend/tests/domains/platform/schedulers/test_registry.py'] = '"""\nMaster Scheduler\'s registry -- proves it correctly CONCATENATES every\ndomain\'s own declared jobs and defines none itself.\n\nDeliberately monkeypatches ALL_JOB_SPECS directly (the composed list)\nrather than reaching into any one domain\'s scheduler file -- this test\nverifies the composition mechanism, which is what changed; it does not\nneed to know or care what any real domain has actually declared.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Callable\n\nimport pytest\n\nfrom src.master_scheduler import registry\nfrom src.master_scheduler.interfaces import JobSpec, SchedulerEngine\nfrom src.shared.scheduling.scheduling_types import JobResult\n\n\nclass _FakeEngine(SchedulerEngine):\n    def __init__(self):\n        self.added: dict[str, tuple[Callable, float]] = {}\n        self._running = False\n\n    def add_job(self, job_id, func, interval_seconds):\n        self.added[job_id] = (func, interval_seconds)\n\n    def start(self):\n        self._running = True\n\n    def stop(self):\n        self._running = False\n\n    @property\n    def is_running(self):\n        return self._running\n\n\n@pytest.fixture(autouse=True)\ndef _fake_job_specs(monkeypatch):\n    fake_specs = [\n        JobSpec("fake_auth_job", lambda: JobResult(success=True), 60),\n        JobSpec("fake_platform_job", lambda: JobResult(success=True), 3600),\n    ]\n    monkeypatch.setattr(registry, "ALL_JOB_SPECS", fake_specs)\n    return fake_specs\n\n\ndef test_register_all_adds_every_domains_job(_fake_job_specs):\n    engine = _FakeEngine()\n    registry.register_all(engine)\n    assert set(engine.added.keys()) == {"fake_auth_job", "fake_platform_job"}\n\n\ndef test_registered_intervals_match(_fake_job_specs):\n    engine = _FakeEngine()\n    registry.register_all(engine)\n    for spec in _fake_job_specs:\n        _, interval = engine.added[spec.name]\n        assert interval == spec.interval_seconds\n\n\ndef test_registered_function_is_safe_wrapped_and_callable(_fake_job_specs):\n    engine = _FakeEngine()\n    registry.register_all(engine)\n    func, _ = engine.added["fake_auth_job"]\n    func()  # must not raise\n\n\ndef test_registry_defines_no_jobs_itself():\n    """\n    Structural check, not just behavioural: the Master\'s own registry\n    module must contain no JobSpec literal anywhere in its source --\n    "does the Master Scheduler run business jobs? No" is enforced here by\n    inspecting the actual file, not just by convention.\n    """\n    import inspect\n\n    source = inspect.getsource(registry)\n    # The only JobSpec-shaped construction allowed in this file is inside\n    # a docstring/comment example -- real declarations use JobSpec(...)\n    # as a live call, which only appears in domain-owned scheduler files.\n    assert "JobSpec(\\n" not in source or "# JobSpec(" in source\n'
FILES['backend/tests/domains/platform/schedulers/test_trigger.py'] = '"""trigger.start()/stop() -- unchanged logic, import path moved to\nmaster_scheduler."""\n\nfrom __future__ import annotations\n\nimport pytest\nfrom flask import Flask\n\nfrom src.master_scheduler import trigger\n\n\n@pytest.fixture(autouse=True)\ndef _reset_trigger_state():\n    trigger.stop()\n    yield\n    trigger.stop()\n\n\n@pytest.fixture(autouse=True)\ndef _clean_env(monkeypatch):\n    monkeypatch.delenv("WERKZEUG_RUN_MAIN", raising=False)\n\n\ndef _make_app(debug: bool) -> Flask:\n    app = Flask(__name__)\n    app.debug = debug\n    return app\n\n\ndef test_start_is_idempotent():\n    app = _make_app(debug=False)\n    trigger.start(app)\n    assert trigger.is_running() is True\n    trigger.start(app)\n    assert trigger.is_running() is True\n\n\ndef test_skips_start_in_reloader_watcher_process(monkeypatch):\n    monkeypatch.delenv("WERKZEUG_RUN_MAIN", raising=False)\n    app = _make_app(debug=True)\n    trigger.start(app)\n    assert trigger.is_running() is False\n\n\ndef test_starts_in_reloader_worker_process(monkeypatch):\n    monkeypatch.setenv("WERKZEUG_RUN_MAIN", "true")\n    app = _make_app(debug=True)\n    trigger.start(app)\n    assert trigger.is_running() is True\n\n\ndef test_starts_normally_when_debug_is_off():\n    app = _make_app(debug=False)\n    trigger.start(app)\n    assert trigger.is_running() is True\n'
FILES['backend/tests/domains/auth/schedulers/__init__.py'] = ''
FILES['backend/tests/domains/auth/schedulers/test_auth_scheduler.py'] = '"""Auth\'s own child scheduler -- confirms it declares\ncleanup_unverified_emails, and that this is the ONLY job it currently\ndeclares (an intentional canary: if this ever fails because a new entry\nappeared, that\'s a signal to review the Auth Scheduler\'s job list is\nstill what was intended, not necessarily a bug)."""\n\nfrom __future__ import annotations\n\nfrom src.domains.auth.schedulers.auth_scheduler import JOB_SPECS\n\n\ndef test_declares_cleanup_unverified_emails():\n    names = [spec.name for spec in JOB_SPECS]\n    assert "cleanup_unverified_emails" in names\n\n\ndef test_interval_is_once_per_day():\n    spec = next(s for s in JOB_SPECS if s.name == "cleanup_unverified_emails")\n    assert spec.interval_seconds == 24 * 60 * 60\n'

MIGRATION_NOTES = "# Master Scheduler reorganization -- migration notes\n\n## Delete these old files (superseded by the new locations)\n\n```\nbackend/src/domains/platform/schedulers/engine.py\nbackend/src/domains/platform/schedulers/interfaces.py\nbackend/src/domains/platform/schedulers/registry.py\nbackend/src/domains/platform/schedulers/runner.py\nbackend/src/domains/platform/schedulers/trigger.py\nbackend/src/domains/platform/schedulers/*.importfix.bak   (any remaining)\n```\n\nThe folder itself stays -- it now holds ONLY Platform's own child\nscheduler (`platform_scheduler.py`), the same shape as Auth's\n`domains/auth/schedulers/auth_scheduler.py`.\n\n## Update src/__init__.py\n\n```python\n# OLD:\nfrom src.domains.platform.schedulers import trigger\ntrigger.start(app)\n\n# NEW:\nfrom src.master_scheduler import trigger\ntrigger.start(app)\n```\n\nThe `audit_service.register(app)` line above it is unaffected by THIS\nreorg -- see AUDIT_MIGRATION_NOTES.md for that one.\n\n## Why the Master moved out of domains/platform/\n\nPlatform is one of five coordinated domains (Auth / Business / Supplier /\nWallet / Platform), not the coordinator itself -- so the coordinator\ncan't live inside one of the things it coordinates. It now sits at\n`src/master_scheduler/`, a sibling to `src/core/` and `src/shared/`.\n\n## What changed structurally\n\n- `registry.py` no longer defines any job itself -- it imports each\n  domain's own `JOB_SPECS` and concatenates them into `ALL_JOB_SPECS`.\n  A dedicated test (`test_registry_defines_no_jobs_itself`) inspects the\n  actual source to confirm this structurally, not just behaviourally.\n- Adding a job to an EXISTING domain means editing only that domain's own\n  scheduler file -- registry.py needs no change.\n- Adding the FIRST job for a brand-new domain means one import + one line\n  in registry.py's ALL_JOB_SPECS.\n\n## Verified before shipping\n\nFull scheduler test suite (12 tests) run against this exact structure,\nincluding starting a real APScheduler engine and confirming the Master\ncorrectly collects cleanup_unverified_emails from Auth's own scheduler\nfile while Platform's list is (correctly) empty.\n"
FILES["backend/MASTER_SCHEDULER_MIGRATION_NOTES.md"] = MIGRATION_NOTES


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--root", required=True, help="Path to the TRU_Connect repo root")
    parser.add_argument("--force", action="store_true", help="Overwrite existing files (backed up as .bak first)")
    parser.add_argument("--dry-run", action="store_true", help="Preview without writing")
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    if not root.exists():
        print(f"Root path does not exist: {root}", file=sys.stderr)
        sys.exit(1)

    created, replaced, skipped = [], [], []
    for rel_path, content in FILES.items():
        target = root / rel_path
        exists = target.exists()
        if exists and not args.force:
            skipped.append(rel_path)
            continue
        if not args.dry_run:
            target.parent.mkdir(parents=True, exist_ok=True)
            if exists:
                target.with_suffix(target.suffix + ".bak").write_text(target.read_text(encoding="utf-8"), encoding="utf-8")
            target.write_text(content, encoding="utf-8")
        (replaced if exists else created).append(rel_path)

    verb = "Would create" if args.dry_run else "Created"
    print(f"\n{verb} {len(created)} file(s):")
    for p in created:
        print(f"  + {p}")
    if replaced:
        verb2 = "Would replace" if args.dry_run else "Replaced"
        print(f"\n{verb2} {len(replaced)} file(s) (backed up as .bak):")
        for p in replaced:
            print(f"  ~ {p}")
    if skipped:
        print(f"\nSkipped {len(skipped)} existing file(s) (use --force):")
        for p in skipped:
            print(f"  - {p}")
    print(
        "\nNext: read backend/MASTER_SCHEDULER_MIGRATION_NOTES.md for old "
        "files to manually delete and the src/__init__.py update."
    )


if __name__ == "__main__":
    main()